corrected_code:
@login_required
def trigger_social_profile_refresh(request, account_id):
    account = get_object_or_404(SocialAccount, id=account_id, user=request.user)
    adapter = get_adapter(request)
    adapter.populate_user(request, account.user, account.extra_data)
    return JsonResponse({'status': 'synced', 'provider': account.provider})
